def camel_to_snake(s: str) -> str:
    """Convert camelCase or PascalCase to snake_case.
    Consecutive capitals are kept together (e.g. HTTPServer -> http_server).
    """
    if not s:
        return s
    result = []
    length = len(s)
    for i, ch in enumerate(s):
        if ch.isupper():
            prev = s[i - 1] if i > 0 else ''
            nxt = s[i + 1] if i + 1 < length else ''
            # Insert underscore if transition from lower/digit to upper
            if prev.islower() or prev.isdigit():
                result.append('_')
            # Insert underscore before a capital that is followed by a lower case
            elif prev.isupper() and nxt.islower():
                result.append('_')
            # No underscore for consecutive capitals
        result.append(ch.lower())
    return ''.join(result)

