def camel_to_snake(s: str) -> str:
    """Convert camelCase or PascalCase to snake_case. Consecutive capitals stay together (HTTPServer -> http_server)."""
    if not s:
        return s
    result = []
    i = 0
    n = len(s)
    while i < n:
        # detect a sequence of uppercase letters followed by a lowercase letter or end
        start = i
        while i < n and s[i].isupper():
            i += 1
        # if the sequence is followed by a lowercase letter, treat last uppercase as start of next word
        if i < n and s[i].islower() and i - start > 1:
            # keep all but last uppercase as part of word
            seq = s[start:i-1]
            result.append(seq.lower())
            # start new word with last uppercase
            result.append(s[i-1].lower())
        else:
            seq = s[start:i]
            result.append(seq.lower())
        if i < n and s[i].islower():
            # consume following lowercase letters
            start = i
            while i < n and s[i].islower():
                i += 1
            result.append(s[start:i])
    return '_'.join(result)

