    return not stack

def run_length_encode(s: str) -> str:
    """Compress runs of repeated characters as <char><count>. Single characters keep count 1."""
    if not s:
        return ""
    result = []
    prev = s[0]
    count = 1
    for ch in s[1:]:
        if ch == prev:
            count += 1
        else:
            result.append(f"{prev}{count}")
            prev = ch
            count = 1
    result.append(f"{prev}{count}")
    return "".join(result)

def parse_price(s: str) -> float:
    """Parse a US-formatted price string like '$1,200.50' into a float."""
    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    # Strip leading/trailing whitespace
    s = s.strip()
    if not s:
        raise ValueError("Empty string is not a valid price")
    # Remove leading '$' if present
    if s[0] == '$':
        s = s[1:]
    # Remove commas
    s = s.replace(',', '')
    # Validate remaining pattern: optional digits, optional decimal part
    import re
    if not re.fullmatch(r"\d+(\.\d{1,2})?", s):
        raise ValueError(f"Invalid price format: {s}")
    return float(s)

